 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            objects.append((color, cells))
    if not objects:
        return [row[:] for row in grid]
    top = min(r for _, cells in objects for r, _ in cells)
    out = [[0] * w for _ in range(h)]
    for color, cells in objects:
        own_top = min(r for r, _ in cells)
        shift = top - own_top
        for r, c in cells:
            nr = r + shift
            if 0 <= nr < h:
                out[nr][c] = color
    return out


if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
